#include <stdio.h>
#include <stdint.h>

int main() {
    uint64_t satp_test = (8ULL << 60); // SV39 mode, PPN 0
    uint64_t satp_read = 0;

    // We should be careful: writing satp with 8ULL << 60 and PPN 0 might immediately trap if translation is enabled and no valid page table exists!
    // But wait, if we are in M-mode, does writing satp affect us?
    // In RISC-V, satp only affects S-mode and U-mode translations. In M-mode, translation is always disabled unless MPRV is set in mstatus.
    // So writing satp in M-mode should NOT affect M-mode execution, and we can read it back to see if the write is preserved (which checks if S-mode/SV39 is supported in HW).

    asm volatile ("csrw satp, %0" : : "r"(satp_test));
    asm volatile ("csrr %0, satp" : "=r"(satp_read));

    printf("Wrote: 0x%lx, Read: 0x%lx\n", satp_test, satp_read);
    return 0;
}

