#include <stdio.h>
#include <stdint.h>

#define PTE_V     (1ULL << 0)
#define PTE_R     (1ULL << 1)
#define PTE_W     (1ULL << 2)
#define PTE_X     (1ULL << 3)
#define PTE_U     (1ULL << 4)
#define PTE_G     (1ULL << 5)
#define PTE_A     (1ULL << 6)
#define PTE_D     (1ULL << 7)

uint64_t l2_pt[512] __attribute__((aligned(4096)));
uint64_t l1_pt[512] __attribute__((aligned(4096)));
uint64_t l0_pt_a[512] __attribute__((aligned(4096)));
uint64_t l0_pt_b[512] __attribute__((aligned(4096)));

uint8_t pages_a[512][4096] __attribute__((aligned(4096)));
uint8_t pages_b[512][4096] __attribute__((aligned(4096)));

void init_page_tables() {
    for (int i = 0; i < 512; i++) {
        l2_pt[i] = 0;
        l1_pt[i] = 0;
        l0_pt_a[i] = 0;
        l0_pt_b[i] = 0;
    }

    // Root level (Level 2):
    // Map 0x80000000 to 0xBFFFFFFF (1GB) as identity superpage
    l2_pt[2] = ((0x80000ULL) << 10) | PTE_V | PTE_R | PTE_W | PTE_X | PTE_A | PTE_D;

    // Map 0xC0000000 to 0xFFFFFFFF to Level 1 page table
    l2_pt[3] = ((((uint64_t)l1_pt) >> 12) << 10) | PTE_V;

    // Level 1:
    l1_pt[0] = ((((uint64_t)l0_pt_a) >> 12) << 10) | PTE_V;
    l1_pt[1] = ((((uint64_t)l0_pt_b) >> 12) << 10) | PTE_V;

    // Level 0:
    for (int i = 0; i < 512; i++) {
        uint64_t ppn_a = ((uint64_t)&pages_a[i]) >> 12;
        l0_pt_a[i] = (ppn_a << 10) | PTE_V | PTE_R | PTE_W | PTE_X | PTE_A | PTE_D;

        uint64_t ppn_b = ((uint64_t)&pages_b[i]) >> 12;
        l0_pt_b[i] = (ppn_b << 10) | PTE_V | PTE_R | PTE_W | PTE_X | PTE_A | PTE_D;
    }
}

int main() {
    printf("Initializing page tables...\n");
    init_page_tables();

    printf("Entering S-mode with SV39 enabled...\n");
    uint64_t satp_val = (8ULL << 60) | (((uint64_t)l2_pt) >> 12);

    asm volatile (
        "csrw satp, %0\n\t"
        "sfence.vma\n\t"
        "li t0, 0x1800\n\t"
        "csrc mstatus, t0\n\t"
        "li t0, 0x0800\n\t"
        "csrs mstatus, t0\n\t"
        "la t0, 1f\n\t"
        "csrw mepc, t0\n\t"
        "mret\n"
        "1:\n\t"
        :
        : "r"(satp_val)
        : "t0", "memory"
    );

    printf("Successfully running in S-mode!\n");

    // Let's test accessing the mapped pages
    volatile uint8_t* ptr_a0 = (volatile uint8_t*)0xC0000000;
    volatile uint8_t* ptr_b0 = (volatile uint8_t*)0xC0200000;

    *ptr_a0 = 0xAA;
    *ptr_b0 = 0x55;

    printf("Read ptr_a0: 0x%x (expected 0xaa)\n", *ptr_a0);
    printf("Read ptr_b0: 0x%x (expected 0x55)\n", *ptr_b0);

    return 0;
}

