#include <stdio.h>
#include <stdint.h>

#define PTE_V     (1ULL << 0)
#define PTE_R     (1ULL << 1)
#define PTE_W     (1ULL << 2)
#define PTE_X     (1ULL << 3)
#define PTE_U     (1ULL << 4)
#define PTE_G     (1ULL << 5)
#define PTE_A     (1ULL << 6)
#define PTE_D     (1ULL << 7)

#define MSTATUS_MPRV (1ULL << 17)
#define MSTATUS_MPP_MASK (3ULL << 11)
#define MSTATUS_MPP_S    (1ULL << 11)

uint64_t l2_pt[512] __attribute__((aligned(4096)));
uint64_t l1_pt[512] __attribute__((aligned(4096)));
uint8_t page_data[4096] __attribute__((aligned(4096)));

void init_page_tables() {
    for (int i = 0; i < 512; i++) {
        l2_pt[i] = 0;
        l1_pt[i] = 0;
    }

    // Root level (Level 2):
    // Map 0x80000000 to 0xBFFFFFFF as identity superpage
    l2_pt[2] = ((0x80000ULL) << 10) | PTE_V | PTE_R | PTE_W | PTE_X | PTE_A | PTE_D;

    // Map virtual page 0xC0000000 to l1_pt
    l2_pt[3] = ((((uint64_t)l1_pt) >> 12) << 10) | PTE_V;

    // Level 1:
    // Map virtual page 0xC0000000 (which is index 0 in level 1 if we use it) to page_data
    // Wait, 0xC0000000 virtual address VPN is:
    // VPN[2] = (0xC0000000 >> 30) & 0x1FF = 3
    // VPN[1] = (0xC0000000 >> 21) & 0x1FF = 0
    // VPN[0] = (0xC0000000 >> 12) & 0x1FF = 0
    l1_pt[0] = ((((uint64_t)page_data) >> 12) << 10) | PTE_V | PTE_R | PTE_W | PTE_X | PTE_A | PTE_D;
}

int main() {
    printf("Initializing page tables...\n");
    init_page_tables();

    uint64_t satp_val = (8ULL << 60) | (((uint64_t)l2_pt) >> 12);

    page_data[0] = 0xAA;

    printf("Enabling MPRV...\n");

    uint64_t mstatus_val;
    asm volatile ("csrr %0, mstatus" : "=r"(mstatus_val));
    mstatus_val &= ~MSTATUS_MPP_MASK;
    mstatus_val |= MSTATUS_MPP_S; // Set MPP to S-mode

    asm volatile ("csrw satp, %0" : : "r"(satp_val));
    asm volatile ("sfence.vma");

    // Enable MPRV
    uint64_t mstatus_mprv = mstatus_val | MSTATUS_MPRV;

    uint8_t read_val = 0;

    // We must be extremely careful: any load/store while MPRV=1 is translated.
    // So the stack and everything must be mapped if the compiler generates accesses to them!
    // Since our identity mapping of 0x80000000 (1GB) covers the entire program and stack (all are around 0x80000000),
    // data accesses to stack or globals will be translated successfully via the 1GB identity superpage at l2_pt[2]!
    // Let's do a translated access to 0xC0000000.

    asm volatile (
        "csrw mstatus, %1\n\t"
        "lb %0, 0(%2)\n\t"
        "csrw mstatus, %3\n\t"
        : "=r"(read_val)
        : "r"(mstatus_mprv), "r"(0xC0000000ULL), "r"(mstatus_val)
        : "memory"
    );

    printf("Read via MPRV: 0x%x (expected 0xaa)\n", read_val);

    return 0;
}

