    uint64_t mcause, mepc;
    asm volatile ("csrr %0, mcause" : "=r"(mcause));
    asm volatile ("csrr %0, mepc" : "=r"(mepc));
    printf("Trap caught! mcause = %lu, mepc = 0x%lx\n", mcause, mepc);
    while (1);
}

int main() {
    // Set up mtvec to point to trap_handler
    asm volatile ("csrw mtvec, %0" : : "r"(trap_handler));

    // Trigger instruction page fault by setting satp with a garbage value
    uint64_t satp_val = (8ULL << 60) | (0x12345ULL);

    // Delegate page faults and load/store address misaligned/faults
    uint64_t medeleg_val = 0xFFFFULL; // delegate all exceptions to S-mode?
    // Wait, let's see if we can write medeleg
    uint64_t medeleg_read = 0;
    asm volatile ("csrw medeleg, %0" : : "r"(medeleg_val));
    asm volatile ("csrr %0, medeleg" : "=r"(medeleg_read));

    printf("medeleg read: 0x%lx\n", medeleg_read);
    return 0;
}

