#include <stdint.h>

int main() {
    uint64_t mstatus_val = 0;
    asm volatile ("csrr %0, mstatus" : "=r"(mstatus_val));
    printf("mstatus = 0x%lx\n", mstatus_val);

    // Check if MPRV is writable
    uint64_t mstatus_test = mstatus_val | (1ULL << 17); // MPRV = 1
    // But don't write S-mode MPP yet, just see what happens if we write back mstatus.
    // Wait, writing MPRV=1 with MPP=M-mode (3) is also possible, but translation uses MPP privilege mode.
    // Since MPP is 3 (M-mode), MPRV=1 has NO effect (M-mode is untranslated).
    // Let's test if we can write MPRV=1 with MPP=M-mode.
    asm volatile ("csrw mstatus, %0" : : "r"(mstatus_test));
    uint64_t mstatus_read = 0;
    asm volatile ("csrr %0, mstatus" : "=r"(mstatus_read));

    printf("After writing MPRV=1 with MPP=M-mode, mstatus = 0x%lx\n", mstatus_read);
    return 0;
}

