#include <stdio.h>
#include <stdint.h>

int main() {
    // Let's write PMP to allow everything
    // NAPOT range of all memory: pmpaddr0 = 0xFFFFFFFFFFFFFFFFULL (or just 0x1fffffffULL for 32-bit physical address space)
    // Wait, the physical address width of this BOOM config is 32 bits (as reported in TLB report).
    // Let's use 0xFFFFFFFFFFFFFFFFULL anyway because it is NAPOT for all address space.
    // For NAPOT covering all space, pmpaddr0 should be all 1s.
    uint64_t pmpaddr = 0xFFFFFFFFFFFFFFFFULL;
    uint64_t pmpcfg = 0x1F; // R=1, W=1, X=1, A=NAPOT (3), L=0

    asm volatile ("csrw pmpaddr0, %0" : : "r"(pmpaddr));
    asm volatile ("csrw pmpcfg0, %0" : : "r"(pmpcfg));

    uint64_t pmpcfg_read = 0;
    uint64_t pmpaddr_read = 0;

    asm volatile ("csrr %0, pmpcfg0" : "=r"(pmpcfg_read));
    asm volatile ("csrr %0, pmpaddr0" : "=r"(pmpaddr_read));

    printf("pmpcfg0 = 0x%lx, pmpaddr0 = 0x%lx\n", pmpcfg_read, pmpaddr_read);
    return 0;
}

