#include <stdio.h>
#include <stdint.h>

#define PTE_V     (1ULL << 0)
#define PTE_R     (1ULL << 1)
#define PTE_W     (1ULL << 2)
#define PTE_X     (1ULL << 3)
#define PTE_U     (1ULL << 4)
#define PTE_G     (1ULL << 5)
#define PTE_A     (1ULL << 6)
#define PTE_D     (1ULL << 7)

#define MSTATUS_MPRV (1ULL << 17)
#define MSTATUS_MPP_MASK (3ULL << 11)
#define MSTATUS_MPP_S    (1ULL << 11)

uint64_t l2_pt[512] __attribute__((aligned(4096)));
uint64_t l1_pt[512] __attribute__((aligned(4096)));
uint64_t l0_pt[512] __attribute__((aligned(4096)));
uint8_t page_data[4096] __attribute__((aligned(4096)));

void trap_handler() __attribute__((interrupt, aligned(16)));
void trap_handler() {
    uint64_t mcause, mepc, mtval;
    asm volatile ("csrr %0, mcause" : "=r"(mcause));
    asm volatile ("csrr %0, mepc" : "=r"(mepc));
    asm volatile ("csrr %0, mtval" : "=r"(mtval));
    printf("Trap caught! mcause = %lu, mepc = 0x%lx, mtval = 0x%lx\n", mcause, mepc, mtval);
    while (1);
}

void init_page_tables_3level() {
    for (int i = 0; i < 512; i++) {
        l2_pt[i] = 0;
        l1_pt[i] = 0;
        l0_pt[i] = 0;
    }

    // Root level (Level 2):
    // Map 0x80000000 to 0xBFFFFFFF as identity superpage (1GB)
    l2_pt[2] = ((0x80000ULL) << 10) | PTE_V | PTE_R | PTE_W | PTE_X | PTE_A | PTE_D;

    // Map 0xC0000000 (root index 3) to l1_pt
    l2_pt[3] = ((((uint64_t)l1_pt) >> 12) << 10) | PTE_V;

    // Level 1:
    // Map 0xC0000000 (VPN[1]=0) to l0_pt
    l1_pt[0] = ((((uint64_t)l0_pt) >> 12) << 10) | PTE_V;

    // Level 0:
    // Map 0xC0000000 (VPN[0]=0) to page_data (4KB page)
    l0_pt[0] = ((((uint64_t)page_data) >> 12) << 10) | PTE_V | PTE_R | PTE_W | PTE_X | PTE_A | PTE_D;
}

int main() {
    asm volatile ("csrw mtvec, %0" : : "r"(trap_handler));

    // Configure PMP to allow all accesses in S-mode
    uint64_t pmpaddr = 0xFFFFFFFFFFFFFFFFULL;
    uint64_t pmpcfg = 0x1F; // R=1, W=1, X=1, A=NAPOT, L=0
    asm volatile ("csrw pmpaddr0, %0" : : "r"(pmpaddr));
    asm volatile ("csrw pmpcfg0, %0" : : "r"(pmpcfg));

    printf("Initializing 3-level page tables...\n");
    init_page_tables_3level();

    uint64_t satp_val = (8ULL << 60) | (((uint64_t)l2_pt) >> 12);

    page_data[0] = 0xAA;

    printf("Enabling MPRV...\n");

    uint64_t mstatus_val;
    asm volatile ("csrr %0, mstatus" : "=r"(mstatus_val));

    mstatus_val &= ~MSTATUS_MPP_MASK;
    mstatus_val |= MSTATUS_MPP_S;

    asm volatile ("csrw satp, %0" : : "r"(satp_val));
    asm volatile ("sfence.vma");

    uint64_t mstatus_mprv = mstatus_val | MSTATUS_MPRV;
    uint8_t read_val = 0;

    asm volatile (
        "csrw mstatus, %1\n\t"
        "lb %0, 0(%2)\n\t"
        "csrw mstatus, %3\n\t"
        : "=r"(read_val)
        : "r"(mstatus_mprv), "r"(0xC0000000ULL), "r"(mstatus_val)
        : "memory"
    );

    printf("Read via MPRV: 0x%x (expected 0xaa)\n", read_val);

    return 0;
}

